<?php
require_once __DIR__.'/includes/bootstrap.php';
require_admin();
$notice=''; $error='';
if(is_post()){
  verify_csrf(); $kind=$_POST['kind']??''; $id=(int)($_POST['id']??0);
  try{
    if(!$db) throw new RuntimeException('Database unavailable');
    if($kind==='domain'){
      $reg=(float)$_POST['registration_price']; $ren=(float)$_POST['renewal_price']; $tr=(float)$_POST['transfer_price'];
      if($reg<0||$ren<0||$tr<0) throw new InvalidArgumentException('Prices cannot be negative.');
      $st=$db->prepare('UPDATE domain_pricing SET registration_price=?,renewal_price=?,transfer_price=?,description=?,active=?,sort_order=? WHERE id=?');
      $st->execute([$reg,$ren,$tr,trim($_POST['description']??''),isset($_POST['active'])?1:0,(int)$_POST['sort_order'],$id]);
      $action='domain_pricing_updated';
    } elseif($kind==='product') {
      $monthly=(float)$_POST['monthly_price']; $yearly=(float)$_POST['yearly_price'];
      if($monthly<0||$yearly<0) throw new InvalidArgumentException('Prices cannot be negative.');
      $features=trim($_POST['features_json']??'[]'); $decoded=json_decode($features,true);
      if(!is_array($decoded)) throw new InvalidArgumentException('Features must be a valid JSON array.');
      $st=$db->prepare('UPDATE products SET name=?,short_description=?,monthly_price=?,yearly_price=?,features_json=?,badge=?,active=?,sort_order=? WHERE id=?');
      $st->execute([trim($_POST['name']),trim($_POST['short_description']),$monthly,$yearly,json_encode(array_values($decoded),JSON_UNESCAPED_UNICODE),trim($_POST['badge']??''),isset($_POST['active'])?1:0,(int)$_POST['sort_order'],$id]);
      $action='product_updated';
    } else throw new InvalidArgumentException('Invalid update type.');
    if($db->exec("SELECT 1")!==false){$al=$db->prepare('INSERT INTO audit_log(admin_user_id,action,entity_type,entity_id,details_json) VALUES(?,?,?,?,?)');$al->execute([current_user()['id'],$action,$kind,$id,json_encode(['ip'=>$_SERVER['REMOTE_ADDR']??''])]);}
    $notice='Changes saved successfully.';
  }catch(Throwable $e){$error=$e->getMessage();}
}
$domains=$db?fetch_domain_prices($db):[];$products=$db?$db->query('SELECT * FROM products ORDER BY category,sort_order,id')->fetchAll():[];
