href="admin-custom-hosting.php">🧩 Custom Hosting</a></div><?php if($notice):?><div class="alert success-alert"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="admin-section"><div class="section-head"><span class="eyebrow mint">DOMAINS</span><h2>Domain Pricing</h2></div><div class="admin-table"><?php foreach($domains as $d):?><form method="post" class="admin-row admin-row-wide"><?=csrf_field()?><input type="hidden" name="kind" value="domain"><input type="hidden" name="id" value="<?=$d['id']?>"><div><strong><?=e($d['tld'])?></strong><small>Registration / renewal / transfer</small></div><label>Registration<input type="number" min="0" step="0.01" name="registration_price" value="<?=e($d['registration_price'])?>"></label><label>Renewal<input type="number" min="0" step="0.01" name="renewal_price" value="<?=e($d['renewal_price'])?>"></label><label>Transfer<input type="number" min="0" step="0.01" name="transfer_price" value="<?=e($d['transfer_price'])?>"></label><label>Description<input name="description" value="<?=e($d['description'])?>"></label><label>Order<input type="number" name="sort_order" value="<?=e($d['sort_order'])?>"></label><label class="check"><input type="checkbox" name="active" <?=$d['active']?'checked':''?>> Active</label><button class="btn primary small">Save</button></form><?php endforeach;?></div></section><section class="admin-section"><div class="section-head"><span class="eyebrow mint">CATALOG</span><h2>Hosting, VPS, Dedicated & Other Services</h2></div><div class="admin-table"><?php foreach($products as $p):?><form method="post" class="admin-row admin-row-product"><?=csrf_field()?><input type="hidden" name="kind" value="product"><input type="hidden" name="id" value="<?=$p['id']?>"><div><strong><?=e($p['name'])?></strong><small><?=e($p['category'])?> · <?=e($p['slug'])?></small></div><label>Name<input name="name" value="<?=e($p['name'])?>"></label><label>Description<input name="short_description" value="<?=e($p['short_description'])?>"></label><label>Monthly<input type="number" min="0" step="1" name="monthly_price" value="<?=e($p['monthly_price'])?>"></label><label>Yearly<input type="number" min="0" step="1" name="yearly_price" value="<?=e($p['yearly_price'])?>"></label><label>Badge<input name="badge" value="<?=e($p['badge'])?>" placeholder="POPULAR"></label><label>Features JSON<textarea name="features_json" rows="2"><?=e($p['features_json'])?></textarea></label><label>Order<input type="number" name="sort_order" value="<?=e($p['sort_order'])?>"></label><label class="check"><input type="checkbox" name="active" <?=$p['active']?'checked':''?>> Active</label><button class="btn primary small">Save</button></form><?php endforeach;?></div></section></main><div class="actions" style="margin-top:20px"><a class="btn primary" href="admin-fulfillment.php">Manual Fulfillment Center</a></div><?php require __DIR__.'/includes/footer.php';?></body></html>
